package render

import "strings"

// stopSummary uses only invocation/result metadata, never live job inspection.
// Old persisted presentations are not regenerated by this renderer.
func stopSummary(args, result map[string]any) string {
	text := func(values map[string]any, key string) string {
		value, _ := values[key].(string)
		return strings.Join(strings.Fields(Clean(value)), " ")
	}
	kind, id := text(result, "kind"), text(args, "job_id")
	if child := text(args, "child_id"); child != "" {
		kind, id = "child", child
	}
	if kind == "" {
		kind = "job"
	}
	identity := text(result, "label")
	if identity == "" {
		identity = id
	}
	if identity == "" {
		return "**job_stop**"
	}
	// Clip before escaping so a Markdown escape can never be cut in half.
	return "**job_stop(" + EscapeInline(clip(kind, 32)) + "=" + EscapeInline(clip(identity, 160)) + ")**"
}
